tool_input.new_string:
const homeLoaded = await page.waitForFunction(() => {
  const content = document.querySelector('.screen-content')?.textContent || ''
  return content.includes('物业服务合同备案审核') && content.includes('苏州市智慧物业数字监管协同平台')
}, null, { timeout: 15000 }).then(() => true).catch(() => false)
if (!homeLoaded) {
  const diagnostic = await page.evaluate(() => ({
    url: location.href,
    title: document.title,
    bodyText: document.body?.innerText?.slice(0, 300),
  }))
  throw new Error(`Home data was not rendered: ${JSON.stringify({ diagnostic, apiPaths, pageErrors, consoleErrors, requestFailures })}`)
}
await page.waitForTimeout(400)
